inline bool localWarriorTalentReviewed(uint32_t talentId) {
    for(const auto& r:kLocalWarriorTalentRecords)if(r.talentId==talentId)return true;
    return false;
}
template<class Tables>
inline bool localWarriorTalentRecordMatches(const Tables& t,uint32_t row,const LocalWarriorTalentRecord& r) {
    if(!t.spells||t.spells->getFieldCount()!=234||t.spells->getUInt32(row,0)!=r.spellId)return false;
    for(uint32_t col=1;col<234;++col) {
        if(col>=131&&col<=203)continue;
        uint32_t expected=0;
        for(const auto& [key,value]:r.columns)if(key==col&&key){expected=value;break;}
        if(t.spells->getUInt32(row,col)!=expected)return false;
    }
    return true;
}
template<class Tables>
inline bool decodeClientWarriorTalent(const Tables& t,uint32_t row,LocalSpellDefinition& d) {
    if(d.allowableClasses!=1||!d.talentRank||d.talentRank>5)return false;
    const LocalWarriorTalentRecord* record=nullptr;
    for(const auto& r:kLocalWarriorTalentRecords)if(r.talentId==d.talentId&&r.rank==d.talentRank){record=&r;break;}
    if(!record||record->spellId!=d.id||!localWarriorTalentRecordMatches(t,row,*record))return false;
    const auto u=[&](uint32_t col){return t.spells->getUInt32(row,col);};
    // EffectBasePoints + 1: every record above has EffectDieSides 1.
    const auto amount=[&](uint32_t effect){return int32_t(u(80+effect))+1;};
    const auto duration=u(40);
    if(!warriorProgressionSelfTables(t,duration,duration?-1:0))return false;
    const uint32_t rank=d.talentRank;
    const auto costModifier=[&](uint8_t operation,bool percentage) {
        d.passiveCastModifiers={};auto& mod=d.passiveCastModifiers[0];
        mod.active=true;mod.operation=operation;mod.percentage=percentage;mod.amount=amount(0);
        mod.mask={u(spell335::EffectClassMask),u(spell335::EffectClassMask+1),u(spell335::EffectClassMask+2)};
        d.spellFamily=4;
    };
    switch(d.talentId) {
        case 124: case 146: case 1542: case 1660: // Improved Heroic Strike, Puncture, Improved Execute, Focused Rage
            costModifier(14,false);break; // SPELLMOD_COST, rage in tenths
        case 1864: // Intensify Rage: Bloodrage, Berserker Rage, Recklessness, Death Wish
            costModifier(11,true);break;  // SPELLMOD_COOLDOWN, percent
        case 126: case 131: case 141: case 142: case 158: case 161: case 166: case 1655: {
            // Pure spell modifiers (aura 107 flat, 108 percent) on the warrior's
            // own abilities: Improved Charge (all effects: rage), Improved
            // Overpower (critical chance), Improved Thunder Clap (cost, damage,
            // effect 2: its attack-speed slow), Improved Bloodrage (effect 1:
            // rage), Booming Voice (duration, radius), Improved Demoralizing
            // Shout and Improved Cleave (all effects), Improved Whirlwind (damage).
            d.passiveCastModifiers={};
            for(uint32_t e=0;e<3;++e)if(u(71+e)) {
                auto& mod=d.passiveCastModifiers[e];
                mod.active=true;mod.operation=uint8_t(u(110+e));mod.percentage=u(95+e)==108;mod.amount=amount(e);
                mod.mask={u(spell335::EffectClassMask+e*3),u(spell335::EffectClassMask+e*3+1),u(spell335::EffectClassMask+e*3+2)};
            }
            d.spellFamily=4;break;
        }
        case 136: case 702: // Two-Handed / One-Handed Weapon Specialization (aura 79 on weapons)
            d.passivePhysicalDamagePct=uint8_t(amount(0));d.requiredItemClass=2;
            d.requiredItemSubclasses=u(69);d.requiredInventoryTypes=0;break;
        case 125: // Mace Specialization: aura 280 while a mace is used
            d.passiveWeaponArmorPenetrationPct=uint8_t(amount(0));d.requiredItemClass=2;
            d.requiredItemSubclasses=u(69);d.requiredInventoryTypes=0;break;
        case 138: d.passiveDodgePct=uint8_t(amount(0));break; // Anticipation
        case 130: d.passiveParryPct=uint8_t(amount(0));break; // Deflection
        case 140: // Toughness: item armor (aura 142) and slowing durations (aura 232, MECHANIC_SNARE)
            d.passiveEquipmentArmorPct=uint8_t(amount(0));
            d.passiveMechanicDurationMask[0]=1u<<u(111);d.passiveMechanicDurationPct[0]=int8_t(amount(1));break;
        case 641: // Iron Will: the same reduction on charm (1) and stun (12)
            d.passiveMechanicDurationMask[0]=(1u<<u(110))|(1u<<u(111));d.passiveMechanicDurationPct[0]=int8_t(amount(0));break;
        case 134: // Weapon Mastery: aura 248 on the target's dodge, aura 234 (not stacking) on disarm
            d.passiveTargetDodgeReductionPct=uint8_t(-amount(0));
            d.passiveMechanicDurationMask[0]=1u<<u(111);d.passiveMechanicDurationPct[0]=int8_t(amount(1));
            d.passiveMechanicDurationNotStack[0]=true;break;
        case 1653: case 1862: // Vitality, Strength of Arms: aura 137 twice, aura 240 expertise
            d.passiveTotalStatPct={};
            for(uint32_t e=0;e<2;++e)d.passiveTotalStatPct[u(110+e)]=uint8_t(amount(e));
            d.passiveExpertise=uint8_t(amount(2));break;
        default: return false;
    }
    (void)rank;
    d.passive=true;d.buffSelfOnly=true;d.unsupportedReason.clear();return true;
}
